studio-shell:
max-width: 1680px;
    width: 100%;
    margin: 0 auto;
    padding: 24px 40px 60px;
    color: var(--color-slate-bright);
    box-sizing: border-box;

studio-topbar:
display: flex;
    justify-content: space-between;
    align-items: center;
    padding-bottom: 16px;
    border-bottom: 1px solid var(--color-graphite-border);
    margin-bottom: 24px;

topbar-breadcrumb:
display: flex;
    align-items: center;
    gap: 10px;
    font-size: 13.5px;

nav-back-link:
background: transparent;
    border: none;
    color: var(--color-slate-muted);
    cursor: pointer;
    font-size: 13px;
    padding: 0;
    transition: color 0.15s;

current-crumb:
font-weight: 600;
    color: var(--color-heading);
    max-width: 600px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;

badge-revision:
background: var(--pill-bg);
    border: 1px solid var(--pill-border);
    border-radius: 999px;
    font-size: 11px;
    font-weight: 600;
    padding: 2px 8px;
    color: var(--color-horizon-bright);

btn-ghost:
background: transparent;
    border: 1px solid var(--color-graphite-border);
    border-radius: var(--radius-sm);
    color: var(--color-slate-light);
    padding: 6px 14px;
    font-size: 12.5px;
    cursor: pointer;
    transition: all 0.15s;

btn-publish:
background: linear-gradient(135deg, #2563eb, #7c3aed);
    color: #ffffff;
    border: none;
    border-radius: var(--radius-sm);
    padding: 7px 16px;
    font-size: 12.5px;
    font-weight: 600;
    cursor: pointer;
    transition: opacity 0.15s;
    box-shadow: 0 2px 8px rgba(37, 99, 235, 0.25);

toast:
display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 9px 14px;
    border-radius: var(--radius-sm);
    font-size: 12.5px;
    margin-bottom: 20px;

toast-info:
background: rgba(59, 130, 246, 0.08);
    border: 1px solid rgba(59, 130, 246, 0.25);
    color: var(--color-aurora-bright);

toast-error:
background: rgba(239, 68, 68, 0.08);
    border: 1px solid rgba(239, 68, 68, 0.25);
    color: var(--color-rose);

toast-close:
background: transparent;
    border: none;
    color: inherit;
    cursor: pointer;
    font-size: 12px;
    padding: 2px 6px;
    opacity: 0.7;

intake-studio-grid:
display: grid;
    grid-template-columns: 380px 1fr;
    gap: 32px;
    align-items: start;
    margin-top: 8px;

intake-presets-card:
background: var(--color-graphite);
    border: 1px solid var(--color-graphite-border);
    border-radius: var(--radius-md);
    padding: 20px 22px;

badge-spark:
display: inline-block;
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: var(--color-horizon-bright);
    margin-bottom: 6px;

method-header:
font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: var(--color-slate-muted);
    margin-bottom: 14px;

presets-header:
font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: var(--color-slate-muted);
    display: block;
    margin-bottom: 10px;

preset-pill-btn:
width: 100%;
    background: var(--color-obsidian);
    border: 1px solid var(--color-graphite-border);
    border-radius: var(--radius-sm);
    padding: 12px 14px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    cursor: pointer;
    text-align: left;
    transition: all 0.15s ease;

preset-action:
font-size: 11.5px;
    font-weight: 600;
    color: var(--color-aurora-bright);
    white-space: nowrap;
    margin-left: 8px;

intake-workbench-card:
background: var(--color-graphite);
    border: 1px solid var(--color-graphite-border);
    border-radius: var(--radius-md);
    padding: 24px 28px;

workbench-header:
display: flex;
    justify-content: space-between;
    align-items: flex-start;
    padding-bottom: 16px;
    border-bottom: 1px solid var(--color-graphite-border);
    margin-bottom: 20px;

textarea-label-row:
display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 5px;

btn-sample-link:
background: transparent;
    border: none;
    color: var(--color-horizon-bright);
    font-size: 11.5px;
    font-weight: 600;
    cursor: pointer;

clean-select:
background: var(--color-obsidian);
    border: 1px solid var(--color-graphite-border);
    border-radius: var(--radius-sm);
    padding: 9px 12px;
    font-size: 13px;
    color: var(--color-slate-bright);
    outline: none;
    transition: border-color 0.15s;

clean-textarea:
width: 100%;
    box-sizing: border-box;
    background: var(--color-obsidian);
    border: 1px solid var(--color-graphite-border);
    border-radius: var(--radius-sm);
    padding: 12px 14px;
    font-size: 13px;
    line-height: 1.55;
    color: var(--color-slate-bright);
    outline: none;
    resize: vertical;
    transition: border-color 0.15s;

workbench-footer:
display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 20px;
    padding-top: 14px;
    border-top: 1px solid var(--color-graphite-border);

btn-synthesize:
padding: 11px 24px;
    background: linear-gradient(135deg, #2563eb, #7c3aed);
    color: #ffffff;
    border: none;
    border-radius: var(--radius-md);
    font-size: 13.5px;
    font-weight: 600;
    cursor: pointer;
    transition: opacity 0.15s;
    box-shadow: 0 4px 12px rgba(37, 99, 235, 0.2);
    white-space: nowrap;

workspace-layout:
display: grid;
    grid-template-columns: minmax(430px, 0.82fr) minmax(0, 1.18fr);
    gap: 24px;
    align-items: start;
    transition: grid-template-columns 0.2s ease;

copilot-sidebar:
background: var(--color-graphite);
    border: 1px solid var(--color-graphite-border);
    border-radius: var(--radius-md);
    padding: 18px;
    display: flex;
    flex-direction: column;
    gap: 12px;
    position: sticky;
    top: 16px;
    max-height: calc(100vh - 100px);
    min-height: 560px;
    overflow: hidden;

copilot-header:
display: flex;
    justify-content: space-between;
    align-items: center;
    padding-bottom: 12px;
    border-bottom: 1px solid var(--color-graphite-border);
    gap: 8px;
    flex-shrink: 0;

bot-icon:
align-items: center;
    background: linear-gradient(135deg, #2563eb, #7c3aed);
    border-radius: 9px;
    color: white;
    display: inline-flex;
    font-size: 17px;
    height: 30px;
    justify-content: center;
    width: 30px;

copilot-collapse:
background: transparent;
    border: 1px solid var(--color-graphite-border);
    border-radius: var(--radius-xs);
    color: var(--color-slate-light);
    cursor: pointer;
    font-size: 12px;
    height: 26px;
    width: 26px;

copilot-context:
align-items: flex-start;
    background: rgba(59, 130, 246, 0.08);
    border: 1px solid rgba(59, 130, 246, 0.24);
    border-radius: var(--radius-sm);
    display: flex;
    gap: 10px;
    justify-content: space-between;
    padding: 10px 12px;
    flex-shrink: 0;

ai-diff-banner:
background: rgba(59, 130, 246, 0.07);
    border: 1px solid rgba(59, 130, 246, 0.2);
    border-radius: var(--radius-xs);
    padding: 8px 10px;
    font-size: 11.5px;
    line-height: 1.4;

diff-title:
font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
    color: var(--color-aurora-bright);
    margin-bottom: 2px;

critique-section:
display: flex;
    flex-direction: column;
    gap: 6px;
    flex-shrink: 0;

critique-header:
display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 11px;
    font-weight: 600;
    color: var(--color-slate-muted);
    text-transform: uppercase;
    letter-spacing: 0.4px;

toggle-btn:
background: transparent;
    border: none;
    color: var(--color-aurora-bright);
    font-size: 10.5px;
    cursor: pointer;
    padding: 0;

prompt-chip:
text-align: left;
    background: var(--pill-bg);
    border: 1px solid var(--pill-border);
    border-radius: var(--radius-xs);
    padding: 7px 9px;
    font-size: 10.5px;
    color: var(--color-slate-bright);
    cursor: pointer;
    transition: all 0.12s;

chat-stream:
display: flex;
    flex-direction: column;
    gap: 8px;
    flex: 1;
    min-height: 170px;
    overflow-y: auto;
    padding: 2px 2px 2px 0;

chat-empty:
align-items: center;
    color: var(--color-slate-muted);
    display: flex;
    flex: 1;
    flex-direction: column;
    font-size: 11.5px;
    justify-content: center;
    line-height: 1.5;
    padding: 20px;
    text-align: center;

chat-user:
background: rgba(59, 130, 246, 0.1);
    color: var(--color-slate-bright);
    border-left: 2px solid var(--color-aurora-bright);

chat-assistant:
background: var(--pill-bg);
    color: var(--color-slate-bright);
    border-left: 2px solid var(--color-horizon-blue);

copilot-input-bar:
display: flex;
    flex-direction: column;
    gap: 6px;
    margin-top: auto;
    border-top: 1px solid var(--color-graphite-border);
    padding-top: 12px;
    flex-shrink: 0;

chat-input:
background: var(--color-obsidian);
    border: 1px solid var(--color-graphite-border);
    border-radius: var(--radius-xs);
    padding: 10px;
    font-size: 12px;
    color: var(--color-slate-bright);
    outline: none;
    resize: none;

btn-send-revision:
background: var(--color-heading);
    color: var(--color-obsidian);
    border: none;
    border-radius: var(--radius-xs);
    padding: 8px 12px;
    font-size: 11.5px;
    font-weight: 600;
    cursor: pointer;

course-summary-card:
background: var(--color-graphite);
    border: 1px solid var(--color-graphite-border);
    border-radius: var(--radius-md);
    padding: 20px 24px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 24px;

summary-card-left:
flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 6px;

course-meta-tags:
display: flex;
    gap: 8px;
    align-items: center;
    flex-wrap: wrap;
    margin-bottom: 2px;

meta-tag:
font-size: 11px;
    font-weight: 600;
    padding: 2px 8px;
    border-radius: 999px;
    background: var(--pill-bg);
    border: 1px solid var(--pill-border);
    color: var(--color-slate-muted);

tag-domain:
color: var(--color-aurora-bright);
    background: rgba(59, 130, 246, 0.08);
    border-color: rgba(59, 130, 246, 0.2);

summary-card-stats:
display: flex;
    gap: 18px;
    flex-shrink: 0;
    padding-left: 24px;
    border-left: 1px solid var(--color-graphite-border);

padding-left: 0;
      border-left: none;
      border-top: 1px solid var(--color-graphite-border);
      padding-top: 12px;
      width: 100%;
      justify-content: space-around;

stat-box:
display: flex;
    flex-direction: column;
    align-items: center;
    min-width: 60px;

stat-lbl:
font-size: 10px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.4px;
    color: var(--color-slate-muted);
    margin-top: 2px;

course-title-clean:
background: transparent;
    border: none;
    color: var(--color-heading);
    font-size: 20px;
    font-weight: 700;
    outline: none;
    padding: 0;
    width: 100%;

course-overview-clean:
background: transparent;
    border: none;
    color: var(--color-slate-light);
    font-size: 13px;
    line-height: 1.5;
    outline: none;
    resize: none;
    padding: 0;
    width: 100%;

units-toolbar:
display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0 4px;

toolbar-actions:
display: flex;
    align-items: center;
    gap: 8px;
    font-size: 11.5px;

link-action:
background: transparent;
    border: none;
    color: var(--color-slate-muted);
    cursor: pointer;
    font-size: 11.5px;
    padding: 0;

btn-add-unit:
background: var(--pill-bg);
    border: 1px solid var(--pill-border);
    color: var(--color-slate-bright);
    border-radius: var(--radius-xs);
    padding: 3px 8px;
    font-size: 11.5px;
    font-weight: 600;
    cursor: pointer;

unit-card:
background: var(--color-graphite);
    border: 1px solid var(--color-graphite-border);
    border-radius: var(--radius-md);
    overflow: hidden;
    transition: box-shadow 0.15s ease, border-color 0.15s ease;

unit-bar:
padding: 12px 18px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 16px;
    cursor: pointer;
    background: var(--color-graphite-card);
    user-select: none;

unit-bar-left:
display: flex;
    align-items: center;
    gap: 12px;
    flex: 1;
    min-width: 0;
    overflow: hidden;

unit-pill:
background: var(--pill-bg);
    border: 1px solid var(--pill-border);
    border-radius: var(--radius-xs);
    font-size: 10.5px;
    font-weight: 700;
    text-transform: uppercase;
    padding: 2px 6px;
    color: var(--color-slate-muted);
    flex-shrink: 0;

unit-title-text:
background: transparent;
    border: none;
    color: var(--color-heading);
    font-size: 14px;
    font-weight: 600;
    outline: none;
    flex: 1;
    min-width: 0;
    cursor: text;
    text-overflow: ellipsis;
    white-space: nowrap;
    overflow: hidden;

border-bottom: 1px solid var(--color-horizon-blue);
    text-overflow: clip;
    overflow: visible;

tag-pill:
font-size: 9.5px;
    font-weight: 700;
    text-transform: uppercase;
    padding: 1px 6px;
    border-radius: 999px;
    flex-shrink: 0;

unit-bar-right:
display: flex;
    align-items: center;
    gap: 10px;
    flex-shrink: 0;

btn-focus-copilot:
background: transparent;
    border: 1px solid var(--pill-border);
    border-radius: 999px;
    color: var(--color-slate-light);
    cursor: pointer;
    font-size: 10px;
    font-weight: 600;
    padding: 4px 8px;

active:
background: rgba(59, 130, 246, 0.14);
    border-color: rgba(59, 130, 246, 0.5);
    color: var(--color-horizon-bright);

btn-del-unit:
background: transparent;
    border: none;
    cursor: pointer;
    font-size: 11px;
    opacity: 0.6;
    padding: 2px 4px;

chevron:
font-size: 10px;
    color: var(--color-slate-muted);
    width: 14px;
    text-align: center;

unit-expanded-content:
padding: 16px 20px 20px;
    border-top: 1px solid var(--color-graphite-border);
    background: var(--color-graphite);

unit-two-col-grid:
display: grid;
    grid-template-columns: 1.15fr 0.85fr;
    gap: 24px;
    align-items: start;

field-row-header:
display: flex;
    justify-content: space-between;
    align-items: center;

field-title:
font-size: 10.5px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.4px;
    color: var(--color-slate-muted);

btn-text-action:
background: transparent;
    border: none;
    color: var(--color-aurora-bright);
    font-size: 11px;
    font-weight: 600;
    cursor: pointer;
    padding: 0;

clean-textarea-sm:
background: var(--color-obsidian);
    border: 1px solid var(--color-graphite-border);
    border-radius: var(--radius-xs);
    padding: 10px 12px;
    font-size: 12.5px;
    color: var(--color-slate-bright);
    line-height: 1.5;
    outline: none;
    resize: vertical;

obj-row:
display: flex;
    align-items: center;
    gap: 8px;
    padding: 2px 0;

obj-text-input:
flex: 1;
    background: transparent;
    border: none;
    border-bottom: 1px dashed transparent;
    color: var(--color-slate-bright);
    font-size: 12.5px;
    padding: 3px 0;
    outline: none;

btn-remove-obj:
background: transparent;
    border: none;
    color: var(--color-slate-subtle);
    cursor: pointer;
    font-size: 10px;
    padding: 2px 4px;

assessment-milestone-box:
background: var(--color-obsidian);
    border: 1px solid var(--color-graphite-border);
    border-radius: var(--radius-sm);
    padding: 14px 16px;
    display: flex;
    flex-direction: column;
    gap: 6px;

milestone-badge:
font-size: 10.5px;
    font-weight: 700;
    text-transform: uppercase;
    color: var(--color-horizon-bright);
    letter-spacing: 0.4px;

source-section-lbl:
font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.4px;
    color: var(--color-slate-muted);
    margin-top: 4px;

source-pill:
font-size: 11px;
    background: var(--pill-bg);
    border: 1px solid var(--pill-border);
    border-radius: var(--radius-xs);
    padding: 3px 8px;
    color: var(--color-slate-bright);

kc-box:
background: var(--color-obsidian);
    border: 1px solid var(--color-graphite-border);
    border-radius: var(--radius-sm);
    padding: 12px 14px;
    display: flex;
    flex-direction: column;
    gap: 8px;

kc-title:
font-size: 10.5px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.4px;
    color: var(--color-slate-muted);

kc-pill:
font-size: 10.5px;
    background: var(--pill-bg);
    border: 1px solid var(--pill-border);
    border-radius: var(--radius-xs);
    padding: 3px 8px;
    color: var(--color-aurora-bright);
    font-family: monospace;

spinner-sm:
display: inline-block;
    width: 12px;
    height: 12px;
    border: 2px solid rgba(255, 255, 255, 0.3);
    border-top-color: #ffffff;
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
    vertical-align: middle;
    margin-right: 6px;

workspace-viewport:
display: flex;
    flex-direction: column;
    height: calc(100vh - 56px);
    background: var(--color-obsidian);
    overflow: hidden;

workspace-topbar:
background: var(--color-graphite);
    border-bottom: 1px solid var(--color-graphite-border);
    padding: 8px 16px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    min-height: 52px;
    flex-shrink: 0;
