topbar-left:
display: flex;
    align-items: center;
    gap: 14px;
    min-width: 0;

sidebar-toggle-btn:
background: var(--color-bone-muted);
    border: 1px solid var(--color-graphite-border);
    border-radius: var(--radius-sm);
    color: var(--color-slate-light);
    font-size: 11px;
    font-weight: 700;
    padding: 6px 10px;
