    box-shadow: 0 0 0 2px rgba(2, 132, 199, 0.2);

eyebrow:
font-size: 9px;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    color: var(--color-horizon-blue);

topbar-right:
display: flex;
    align-items: center;
    gap: 10px;
    flex-shrink: 0;

tutor-toggle-btn:
background: rgba(139, 92, 246, 0.1);
