    border-radius: var(--radius-sm);
    color: #8b5cf6;
    font-size: 11px;
    font-weight: 700;
    padding: 6px 11px;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    cursor: pointer;
    transition: all 0.15s ease;

concept-inquiry-notice:
align-self: center;
    background: transparent;
    border: 1px solid var(--color-graphite-border);
    border-radius: var(--radius-sm);
    color: var(--color-slate-light);
    cursor: pointer;
    font-size: 11px;
    margin: 8px 0 0;
