probe-count-pill:
background: #8b5cf6;
    color: #fff;
    border-radius: 99px;
    padding: 1px 6px;
    font-size: 10px;
    font-weight: 800;

session-badge:
background: var(--color-signal-green-bg);
    border: 1px solid rgba(5, 150, 105, 0.25);
