workspace-horizontal-tabs:
display: flex;
    align-items: center;
    gap: 4px;
    background: var(--pill-bg, rgba(0, 0, 0, 0.04));
    border: 1px solid var(--pill-border, rgba(0, 0, 0, 0.08));
    border-radius: 99px;
    padding: 3px 5px;

tab-btn:
display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 6px 14px;
    border-radius: 99px;
    font-size: 12px;
    font-weight: 600;
    color: var(--color-slate-light);
    background: transparent;
